{"content": "1|// In-memory stand-in for the real network: FakeServer hands out FakeConnection
2|// pairs (server side ↔ client side) whose messages are delivered straight to
3|// the peer's handler — immediately, after N ms on FakeNet's virtual clock, or
4|// never (drop). Race logic (phase 2) is driven end-to-end through these pairs
5|// with deterministic timestamps: no sockets, no real timers.
6|//
7|// The connection shape mirrors the real WsConnection from ws.js:
8|// send(text), close(), onMessage(cb), onClose(cb), plus a server-assigned id.
9|
10|// Virtual clock + FIFO event queue. advance(ms) runs everything that became
11|// due, in schedule order; handlers may schedule follow-ups mid-advance.
12|export class FakeNet {
13|  constructor(start = 0) {
14|    this.now = start;
15|    this.queue = []; // { at, seq, fn }, kept sorted by (at, seq)
16|    this._seq = 0;
17|  }
18|
19|  schedule(delay, fn) {
20|    this.queue.push({ at: this.now + Math.max(0, delay), seq: this._seq++, fn });
21|    this.queue.sort((a, b) => a.at - b.at || a.seq - b.seq);
22|  }
23|
24|  advance(ms) {
25|    const end = this.now + ms;
26|    while (this.queue.length && this.queue[0].at <= end) {
27|      this.now = this.queue[0].at;
28|      this.queue.shift().fn();
29|    }
30|    this.now = end;
31|  }
32|}
33|
34|const resolve = (v) => (typeof v === 'function' ? v() : v);
35|
36|// One end of a wire pair. opts: { latency = 0, drop = false } — plain values or
37|// functions, re-read on every send, so tests can inject jitter or selective loss.
38|export class FakeConnection {
39|  constructor(net, opts = {}) {
40|    this.net = net;
41|    this.opts = opts;
42|    this.id = 0;
43|    this.peer = null;
44|    this.onMessage = null;
45|    this.onClose = null;
46|    this.closed = false;
47|  }
48|
49|  send(text) {
50|    if (this.closed || resolve(this.opts.drop)) return;
51|    const peer = this.peer;
52|    const deliver = () => !peer.closed && peer.onMessage?.(text);
53|    const delay = resolve(this.opts.latency ?? 0);
54|    if (delay > 0) this.net.schedule(delay, deliver); else deliver();
55|  }
56|
57|  // Clean disconnect: the closer learns at once, the peer after the wire delay.
58|  // `code`/`reason` are ignored for delivery but recorded, so tests can verify
59|  // reject messages (the real WsConnection sends them in a close frame).
60|  close(code, reason) {
61|    if (this.closed) return;
62|    this.closed = true;
63|    this.closedWith = { code, reason };
64|    this.onClose?.();
65|    const peer = this.peer;
66|    const notify = () => peer._peerClosed();
67|    const delay = resolve(this.opts.latency ?? 0);
68|    if (delay > 0) this.net.schedule(delay, notify); else notify();
69|  }
70|
71|  _peerClosed() {
72|    if (this.closed) return;
73|    this.closed = true;
74|    this.onClose?.();
75|  }
76|}
77|
78|// Creates the pairs: every connect() makes a server-side connection (handed to
79|// onConnect, with a fresh id) and returns the matching client side.
80|export class FakeServer {
81|  constructor(net) {
82|    this.net = net;
83|    this.onConnect = null;
84|    this._nextId = 1;
85|  }
86|
87|  // Both directions share clientOpts unless serverOpts is given explicitly.
88|  connect(clientOpts = {}, serverOpts = clientOpts) {
89|    const serverConn = new FakeConnection(this.net, serverOpts);
90|    const clientConn = new FakeConnection(this.net, clientOpts);
91|    serverConn.peer = clientConn;
92|    clientConn.peer = serverConn;
93|    serverConn.id = this._nextId++;
94|    this.onConnect?.(serverConn);
95|    return clientConn;
96|  }
97|}", "total_lines": 97, "file_size": 3332, "truncated": false, "is_binary": false, "is_image": false, "not_found": false}

{"content": "1|// The rules of the race as one PURE module: no sockets, no real timers, no
2|// Math.random. Everything that touches the outside world is injected —
3|//
4|//   now()      → server time in ms (the master clock every decision is based on)
5|//   send(conn, type, data)      → deliver an outgoing message
6|//   close(conn, code, reason)   → reject a connection
7|//   schedule(delayMs, fn)       → a cancellable-by-us timer (setTimeout / FakeNet.schedule)
8|//
9|// That keeps the whole state machine (lobby → countdown → racing → finished →
10|// ceremony) runnable in node:test against FakeNet pairs, and lets main.mjs
11|// wire the real WebSocket connections into the same handlers.
12|//
13|// Official order: the server settles finish times — clients only REPORT, so a
14|// lying or late client can't change the podium. Ties go to the earliest report
15|// (arrival order), which keeps the result deterministic.
16|import { decode, encode, MAX_PLAYERS } from './protocol.js';
17|
18|// Close codes for turned-away connections (NOTES.md documents these).
19|export const CLOSE_FULL = 4000; // 4 already in the lobby
20|export const CLOSE_STARTED = 4001; // race already started
21|
22|// The jump-start bonus (phase 4): moving before the shared green costs this
23|// much official time. One constant, set by the server alone — clients only
24|// report the attempt (`jump`), never the sentence.
25|export const JUMP_PENALTY_MS = 3000;
26|
27|export function createRaceState({
28|  seed: initialSeed,
29|  now = Date.now,
30|  send,
31|  close,
32|  schedule,
33|  countdownMs = 3000,
34|  resultsMs = 2000, // pause between the results table and the podium
35|  ceremonyAfterWinnerMs = 30000, // brief rule: ceremony at latest 30 s after the winner
36|}) {
37|  if (!Number.isInteger(initialSeed) || initialSeed < 0) throw new RangeError('raceState: seed must be a non-negative integer');
38|  let seed = initialSeed; // 'Nochmal' bumps this by exactly +1: the rematch drives the NEXT world
39|
40|  const lobby = new Map(); // conn → nothing yet: connected, has not sent join
41|  const players = new Map(); // conn → { id, name, finish: {t, seq} | null, dnf, pen }
42|  let stage = 'lobby';
43|  let nextId = 1;
44|  let reportSeq = 0; // arrival order of finish reports, breaks time ties deterministically
45|  let goAt = null; // shared start moment, sent in countdown and go
46|  let winnerAt = null; // server time when the first finish was reported
47|  let settled = false; // results are out; final stage change pending
48|
49|  const roster = () => Array.from(players.values(), (p) => ({ id: p.id, name: p.name }));
50|  const broadcast = (type, data) => {
51|    for (const [conn, p] of players) if (!p.gone) send(conn, type, data);
52|  };
53|
54|  const toResults = () => {
55|    const byArrival = Array.from(players.values());
56|    // Official time = reported time + penalty (a jump start pushes a player
57|    // behind a clean finisher with a similar time); ties → earliest report.
58|    const official = (p) => p.finish.t + p.pen;
59|    const finished = byArrival.filter((p) => p.finish).sort((a, b) => official(a) - official(b) || a.finish.seq - b.finish.seq);
60|    // Everyone the race settled without a finish time is a DNF (disconnected
61|    // mid-race, or still driving when the 30 s window forced the result).
62|    const dnf = byArrival.filter((p) => !p.finish).sort((a, b) => a.id - b.id);
63|    return [...finished, ...dnf].map((p) => ({
64|      id: p.id, name: p.name, t: p.finish ? p.finish.t : null, dnf: !p.finish,
65|      pen: p.finish ? p.pen : null, // nothing to penalise without a crossing time
66|    }));
67|  };
68|
69|  // Ceremony fires when everyone is home (finish or DNF — a disconnect never
70|  // blocks it, brief acceptance criterion) or, at the latest, 30 s after the
71|  // winner crossed. Exactly once. An all-DNF race (everyone quits before any
72|  // finish) settles straight away: no winner is coming to save it.
73|  const settle = () => {
74|    if (settled) return;
75|    const allDone = Array.from(players.values()).every((p) => p.finish || p.dnf);
76|    if (!allDone && (winnerAt === null || now() - winnerAt < ceremonyAfterWinnerMs)) return;
77|    settled = true;
78|    stage = 'finished';
79|    const results = toResults();
80|    broadcast('stage', { stage: 'finished' });
81|    broadcast('results', { players: results });
82|    schedule(resultsMs, () => {
83|      stage = 'ceremony';
84|      broadcast('stage', { stage: 'ceremony' });
85|    });
86|  };
87|
88|  const startCountdown = () => {
89|    stage = 'countdown';
90|    goAt = now() + countdownMs;
91|    broadcast('stage', { stage: 'countdown' });
92|    broadcast('countdown', { goAt });
93|    schedule(countdownMs, () => {
94|      stage = 'racing';
95|      broadcast('stage', { stage: 'racing' });
96|      broadcast('go', { goAt });
97|    });
98|  };
99|
100|  // 'Nochmal': only from the ceremony, one press throws the whole race away
101|  // and puts everyone back on a fresh grid — seed + 1 (the players ride the
102|  // NEXT generated world, deterministic), per-player sheet wiped (ids and
103|  // names survive), and the shared-clock countdown starts over.
104|  const rematch = () => {
105|    seed += 1;
106|    reportSeq = 0;
107|    winnerAt = null;
108|    settled = false;
109|    for (const p of players.values()) { p.finish = null; p.dnf = false; p.pen = 0; p.gone = false; } // a dropped socket swallows its sends; its rider settles as DNF again if it never returns
110|    for (const [c] of players) send(c, 'roster', { players: roster(), seed });
111|    startCountdown();
112|  };
113|
114|  // --- Handlers the transport layer calls ---
115|
116|  // A new connection. In-lobby and under the cap → wait for join; anything
117|  // else → turned away with a documented close code before any game message.
118|  const connect = (conn) => {
119|    if (stage !== 'lobby') return close(conn, CLOSE_STARTED, 'race already started');
120|    if (players.size + lobby.size >= MAX_PLAYERS) return close(conn, CLOSE_FULL, 'lobby full');
121|    lobby.set(conn);
122|  };
123|
124|  // One text message from a connection, already framed. Malformed or
125|  // out-of-context messages are dropped silently — no state, no crash.
126|  const onMessage = (conn, text) => {
127|    let m = null;
128|    try { m = decode(text); } catch { return; } // unknown/malformed: drop
129|    const player = players.get(conn);
130|    switch (m.type) {
131|      case 'join': {
132|        if (stage !== 'lobby' || !lobby.has(conn) || player) return;
133|        lobby.delete(conn);
134|        players.set(conn, { id: nextId++, name: m.data.name, finish: null, dnf: false, pen: 0 });
135|        for (const [c] of players) send(c, 'roster', { players: roster(), seed });
136|        break;
137|      }
138|      case 'name': {
139|        if (stage !== 'lobby' || !player) return;
140|        player.name = m.data.name;
141|        broadcast('roster', { players: roster(), seed });
142|        break;
143|      }
144|      case 'start': {
145|        if (stage !== 'lobby' || !player) return; // start gate: ≥ 2 players
146|        if (players.size >= 2) startCountdown();
147|        break;
148|      }
149|      case 'jump': {
150|        // Physics-frozen client tried to move. Only a crime during the
151|        // countdown strictly before green, and only the first one: the server
152|        // alone fixes the penalty, the reporter gets no say in the size of it.
153|        if (stage !== 'countdown' || now() >= goAt || !player || player.gone || player.pen) return;
154|        player.pen = JUMP_PENALTY_MS;
155|        broadcast('jumped', { id: player.id, pen: JUMP_PENALTY_MS });
156|        break;
157|      }
158|      case 'again': {
159|        if (stage !== 'ceremony' || !player || player.gone) return;
160|        rematch();
161|        break;
162|      }
163|      case 'pos': {
164|        if (!['countdown', 'racing', 'finished'].includes(stage) || !player || player.gone) return;
165|        const { x, z, h, s } = m.data;
166|        for (const [other, peer] of players) if (other !== conn && !peer.gone) send(other, 'posRelay', { id: player.id, x, z, h, s });
167|        break;
168|      }
169|      case 'finish': {
170|        // Reports only while actually racing — after the results are settled
171|        // (all home or the 30 s force) a late report would contradict the
172|        // podium every client already received, so it stays DNF.
173|        if (stage !== 'racing' || !player || player.finish || player.dnf) return;
174|        if (m.data.t < 0) return; // negative race times are nonsense, not late
175|        player.finish = { t: m.data.t, seq: reportSeq++ };
176|        if (winnerAt === null) {
177|          winnerAt = now();
178|          schedule(ceremonyAfterWinnerMs, settle); // the race cannot outlive the winner by 30 s
179|        }
180|        broadcast('finishInfo', { id: player.id, t: m.data.t });
181|        settle();
182|        break;
183|      }
184|      case 'ping': {
185|        if (!player && !lobby.has(conn)) return;
186|        send(conn, 'pong', { t: m.data.t, s: now() }); // echo + server clock reading
187|        break;
188|      }
189|    }
190|  };
191|
192|  // A connection went away. Before join → forget it; a racer → marked gone and
193|  // DNF (stays on the podium, never blocks the ceremony); in the lobby → out
194|  // of the roster.
195|  const disconnect = (conn) => {
196|    if (lobby.delete(conn)) return;
197|    const player = players.get(conn);
198|    if (!player || player.gone) return;
199|    player.gone = true;
200|    if (stage === 'lobby') {
201|      players.delete(conn);
202|      broadcast('disconnect', { id: player.id });
203|      broadcast('roster', { players: roster(), seed });
204|      return;
205|    }
206|    player.dnf = true;
207|    broadcast('disconnect', { id: player.id });
208|    settle(); // a DNF can be the last "result" the race was waiting for
209|  };
210|
211|  return { connect, onMessage, disconnect, get stage() { return stage; }, get roster() { return roster(); } };
212|}", "total_lines": 212, "file_size": 9484, "truncated": false, "is_binary": false, "is_image": false, "not_found": false}

{"content": "1|/**
2| * The online client core: connection + lobby flow, one source of race state
3| * for the UI. PURE: the transport (`conn`: send/onMessage/onClose), the clock
4| * (`now`) and the interval helper (`every` → cancel fn) are all injected, so
5| * tests drive whole lobbies over FakeNet on a virtual clock and the browser
6| * wires them to a real WebSocket. `on` is a plain callbacks object.
7| *
8| * Wire messages are JSON text frames, encoded/decoded by server/protocol.js
9| * (plain ES module, browser-safe). Malformed or unknown frames are dropped
10| * silently, exactly like raceState drops its garbage. Counts toward the size
11| * budget — kept tight.
12| */
13|import { decode, encode } from '../../server/protocol.js';
14|import { createClock } from './clock.js';
15|
16|// Close codes the server uses to reject a join (see NOTES.md): a fifth player
17|// in a full lobby (4000), a connection arriving mid-race (4001).
18|const TURNED_AWAY = new Set([4000, 4001]);
19|
20|export function createNetClient({ conn, name, now, every, on }) {
21|  const clock = createClock();
22|  let stage = 'connecting'; // lobby state arrives with the first message
23|  let players = []; // last roster
24|  let seed = null;
25|  let seenSeed = null; // guard so seedChange fires exactly once per distinct seed
26|  let goAt = null; // shared start moment from countdown/go
27|  let finishSent = false; // finishing is once per race
28|  let closed = false;
29|
30|  // ~1 Hz application ping keeps the master clock synced: the pong's echoed
31|  // `t` and server stamp `s`, read with the injected receive time, form one
32|  // min-rtt sample in the clock.
33|  every(1000, () => { if (!closed) conn.send(encode('ping', { t: now() })); });
34|
35|  conn.onMessage = (text) => {
36|    let m = null;
37|    try { m = decode(text); } catch { return; } // malformed/unknown: drop silently
38|    const d = m.data;
39|    switch (m.type) {
40|      case 'roster': // every roster message replaces the local roster
41|        players = d.players;
42|        seed = d.seed;
43|        if (stage === 'connecting') stage = 'lobby'; // a roster IS the lobby: joined and accepted
44|        on.roster?.(players, seed);
45|        if (seed !== seenSeed) { seenSeed = seed; on.seedChange?.(seed); } // rebuild city+mesh
46|        break;
47|      case 'stage':
48|        stage = d.stage;
49|        on.stage?.(stage);
50|        break;
51|      case 'countdown':
52|      case 'go':
53|        goAt = d.goAt;
54|        on.goAt?.(goAt);
55|        break;
56|      case 'posRelay': // stamped with our receive time for the interp buffer
57|        on.peerPos?.({ id: d.id, t: now(), x: d.x, z: d.z, h: d.h, s: d.s });
58|        break;
59|      case 'disconnect':
60|        on.peerGone?.(d.id);
61|        break;
62|      case 'pong':
63|        clock.onPong(d.t, d.s, now());
64|        break;
65|      case 'finishInfo':
66|        on.finishInfo?.({ id: d.id, t: d.t });
67|        break;
68|      case 'results':
69|        on.results?.(d.players);
70|        break;
71|    }
72|  };
73|
74|  conn.onClose = (code, reason) => {
75|    if (closed) return;
76|    closed = true;
77|    if (TURNED_AWAY.has(code)) { stage = 'turnedAway'; on.turnedAway?.(code, reason); }
78|    else { stage = 'dropped'; on.dropped?.(reason); } // missing code = a plain drop
79|  };
80|
81|  conn.send(encode('join', { name }));
82|
83|  // Outgoing helpers. Each send is gated to the stage(s) that make it legal,
84|  // so a UI slip cannot put out-of-context messages on the wire.
85|  const sendIf = (legal, type, data) => { if (!closed && legal) conn.send(encode(type, data)); };
86|
87|  return {
88|    clock, // master clock: the ampel/goAt comparison uses clock.serverNow()
89|    get stage() { return stage; },
90|    get players() { return players; },
91|    get seed() { return seed; },
92|    get canStart() { return stage === 'lobby' && players.length >= 2; },
93|    get goAt() { return goAt; },
94|    /** Stream one car state; legal from the countdown (freeze phase) on. */
95|    sendPos(state) { sendIf(['countdown', 'racing', 'finished'].includes(stage), 'pos', state); },
96|    /** Report the crossing time once per race; legal while racing or after. */
97|    sendFinish(t) {
98|      if (closed || finishSent || (stage !== 'racing' && stage !== 'finished')) return;
99|      finishSent = true;
100|      conn.send(encode('finish', { t }));
101|    },
102|    /** Ask for a race start; only meaningful as two-plus players in the lobby. */
103|    startRace() { sendIf(stage === 'lobby' && players.length >= 2, 'start', {}); },
104|    /** Low-level escape hatch for future phases (e.g. phase-4 rematch). */
105|    sendRaw(text) { if (!closed) conn.send(text); },
106|  };
107|}", "total_lines": 107, "file_size": 4460, "truncated": false, "is_binary": false, "is_image": false, "not_found": false}

{"content": "1|// The multiplayer message language: one entry per message type, declaring its
2|// direction ('cs' client → server, 'sc' server → client), its wire fields and
3|// its design rate. One shared encode/decode pair is driven by those entries,
4|// so every packet is validated against the same definitions that produce the
5|// protocol table in NOTES.md (`node tools/protocol-table.mjs`).
6|//
7|// Wire format: JSON text frames tagged with `type` — messages are tiny and the
8|// intranet is fast, so readable beats compact. All times are milliseconds in
9|// the shared server clock (clients learn their offset via ping/pong, because
10|// the browser's WebSocket API hides the protocol-level ping/pong from JS).
11|
12|export const STAGES = ['lobby', 'countdown', 'racing', 'finished', 'ceremony'];
13|export const MAX_PLAYERS = 4;
14|
15|const err = (where, why) => new Error(`protocol: ${where} ${why}`);
16|
17|// --- Field validators (used by encode AND decode, so both sides agree) ---
18|
19|function str(v, w) {
20|  if (typeof v !== 'string' || v.length < 1 || v.length > 24) throw err(w, 'must be a 1..24 char string');
21|  return v;
22|}
23|function num(v, w) {
24|  if (typeof v !== 'number' || !Number.isFinite(v)) throw err(w, 'must be a finite number');
25|  return v;
26|}
27|function idNum(v, w) {
28|  if (!Number.isInteger(v) || v < 1) throw err(w, 'must be a positive integer');
29|  return v;
30|}
31|function seedNum(v, w) {
32|  if (!Number.isInteger(v) || v < 0) throw err(w, 'must be a non-negative integer');
33|  return v;
34|}
35|function stageOf(v, w) {
36|  if (!STAGES.includes(v)) throw err(w, `must be one of ${STAGES.join('|')}`);
37|  return v;
38|}
39|function rosterOf(v, w) {
40|  if (!Array.isArray(v) || v.length > MAX_PLAYERS) throw err(w, `must be an array of at most ${MAX_PLAYERS} players`);
41|  return v.map((p, i) => {
42|    if (typeof p !== 'object' || p === null || Array.isArray(p)) throw err(`${w}[${i}]`, 'must be an object');
43|    for (const k of Object.keys(p)) if (k !== 'id' && k !== 'name') throw err(`${w}[${i}]`, `has unknown field ${k}`);
44|    if (!('id' in p) || !('name' in p)) throw err(`${w}[${i}]`, 'needs id and name');
45|    return { id: idNum(p.id, `${w}[${i}].id`), name: str(p.name, `${w}[${i}].name`) };
46|  });
47|}
48|
49|const tOrNull = (v, w) => (v === null ? null : num(v, w));
50|// A jump-start penalty: milliseconds the server added to a finisher's time, or
51|// null on a DNF row (no crossing time, nothing to penalise).
52|const penOf = (v, w) => {
53|  if (v === null) return null;
54|  if (typeof v !== 'number' || !Number.isFinite(v) || v < 0) throw err(w, 'must be a non-negative number or null');
55|  return v;
56|};
57|const boolOf = (v, w) => {
58|  if (typeof v !== 'boolean') throw err(w, 'must be a boolean');
59|  return v;
60|};
61|// One results-table row for the settled race: finished players first in
62|// official order (time + penalty, then earliest report), DNFs last with
63|// t = null and pen = null.
64|const resultsOf = (v, w) => {
65|  if (!Array.isArray(v) || v.length > MAX_PLAYERS) throw err(w, `must be an array of at most ${MAX_PLAYERS} players`);
66|  return v.map((r, i) => {
67|    if (typeof r !== 'object' || r === null || Array.isArray(r)) throw err(`${w}[${i}]`, 'must be an object');
68|    for (const k of Object.keys(r)) if (k !== 'id' && k !== 'name' && k !== 't' && k !== 'dnf' && k !== 'pen') throw err(`${w}[${i}]`, `has unknown field ${k}`);
69|    if (!('id' in r) || !('name' in r) || !('t' in r) || !('dnf' in r) || !('pen' in r)) throw err(`${w}[${i}]`, 'needs id, name, t, dnf and pen');
70|    return {
71|      id: idNum(r.id, `${w}[${i}].id`),
72|      name: str(r.name, `${w}[${i}].name`),
73|      t: tOrNull(r.t, `${w}[${i}].t`),
74|      dnf: boolOf(r.dnf, `${w}[${i}].dnf`),
75|      pen: penOf(r.pen, `${w}[${i}].pen`),
76|    };
77|  });
78|};
79|
80|// --- The registry ---
81|
82|export const MESSAGES = {
83|  // client → server
84|  join:       { dir: 'cs', rate: 'once, on entering the lobby', fields: { name: str } },
85|  name:       { dir: 'cs', rate: 'on change, in lobby',          fields: { name: str } },
86|  start:      { dir: 'cs', rate: 'user-triggered',               fields: {} },
87|  pos:        { dir: 'cs', rate: '15 Hz while racing',           fields: { x: num, z: num, h: num, s: num } },
88|  finish:     { dir: 'cs', rate: 'once per race',                fields: { t: num } },
89|  jump:       { dir: 'cs', rate: 'user-triggered, before green', fields: {} },
90|  again:      { dir: 'cs', rate: 'user-triggered, in ceremony',  fields: {} },
91|  ping:       { dir: 'cs', rate: 'about 1 Hz while syncing',     fields: { t: num } },
92|  // server → client
93|  roster:     { dir: 'sc', rate: 'on change',                    fields: { players: rosterOf, seed: seedNum } },
94|  countdown:  { dir: 'sc', rate: 'once per race',                fields: { goAt: num } },
95|  go:         { dir: 'sc', rate: 'once per race',                fields: { goAt: num } },
96|  posRelay:   { dir: 'sc', rate: 'per player, 15 Hz',            fields: { id: idNum, x: num, z: num, h: num, s: num } },
97|  stage:      { dir: 'sc', rate: 'on change',                    fields: { stage: stageOf } },
98|  disconnect: { dir: 'sc', rate: 'on player leaving',            fields: { id: idNum } },
99|  pong:       { dir: 'sc', rate: 'on ping',                      fields: { t: num, s: num } },
100|  finishInfo: { dir: 'sc', rate: 'per finisher, once',           fields: { id: idNum, t: num } },
101|  jumped:     { dir: 'sc', rate: 'per jump, once',              fields: { id: idNum, pen: num } },
102|  results:    { dir: 'sc', rate: 'once, when the race is settled', fields: { players: resultsOf } },
103|};
104|
105|// --- The encode/decode pair ---
106|
107|// encode(type, data) → JSON string, fields validated on the way out.
108|export function encode(type, data) {
109|  const def = MESSAGES[type];
110|  if (!def) throw err(type, 'is not a known message type');
111|  const out = { type };
112|  for (const [f, check] of Object.entries(def.fields)) out[f] = check(data?.[f], `${type}.${f}`);
113|  return JSON.stringify(out);
114|}
115|
116|// decode(text) → { type, data }, or throws on anything unknown or malformed:
117|// bad JSON, non-objects, unknown types, missing/unknown fields, wrong value types.
118|export function decode(text) {
119|  let m = null;
120|  try { m = JSON.parse(text); } catch { /* handled below */ }
121|  if (typeof m !== 'object' || m === null || Array.isArray(m)) throw err('packet', 'must be a JSON object');
122|  const def = MESSAGES[m.type];
123|  if (!def) throw err('packet', `unknown message type ${JSON.stringify(m.type)}`);
124|  const known = Object.keys(def.fields);
125|  for (const k of Object.keys(m)) if (k !== 'type' && !known.includes(k)) throw err(m.type, `unknown field ${k}`);
126|  const data = {};
127|  for (const [f, check] of Object.entries(def.fields)) data[f] = check(m[f], `${m.type}.${f}`);
128|  return { type: m.type, data };
129|}
130|
131|// Markdown table of the whole protocol, generated from the registry. NOTES.md
132|// embeds it between markers; a test keeps the two from drifting apart.
133|export function protocolTable() {
134|  const rows = Object.entries(MESSAGES).map(([name, d]) =>
135|    `| ${name} | ${d.dir === 'cs' ? 'client → server' : 'server → client'} | ${Object.keys(d.fields).join(' ') || '—'} | ${d.rate} |`);
136|  return ['| type | from | fields | rate |', '|---|---|---|---|', ...rows].join('\n');
