{"content": "1|/**
2| * Master-clock maths for the online race. PURE: no DOM, no timers — a client
3| * feeds it pong replies, it keeps the best estimate of the server clock.
4| *
5| * Why the app-level ping/pong instead of WebSocket pings? The browser API
6| * hides protocol-level pings from JavaScript, so the client sends `ping`
7| * {t: local send time}; the server replies `pong` {t: echoed, s: server clock}.
8| * With a roughly symmetric wire, the server's "now" sits in the middle of the
9| * round trip, giving the offset from the client clock to the server clock:
10| *
11| *   rtt    = receiveTime − sentT
12| *   offset = serverS + rtt / 2 − receiveTime   (serverNow = localNow + offset)
13| *
14| * Network jitter inflates individual rtts, so the estimate always comes from
15| * the sample with the SMALLEST rtt of the last N pongs: the fast samples
16| * waited least in queues, so distorted least. Clients keep re-syncing (the
17| * lobby pings at ~1 Hz) before the shared start moment counts down, and the
18| * same serverNow() decides when ONE shared goAt has arrived — so every
19| * client, whatever its wire, flips the ampel to green at the same server
20| * instant.
21| * Counts toward the size budget — kept tight.
22| */
23|
24|/** One clock. history = pong samples kept for the min-rtt filter. */
25|export function createClock(history = 8) {
26|  const samples = []; // {rtt, offset}, newest last
27|  return {
28|    /** Feed one pong: echoedT = our send timestamp echoed back, serverAt = server clock reading, receiveTime = local receive time. */
29|    onPong(echoedT, serverAt, receiveTime) {
30|      const rtt = Math.max(0, receiveTime - echoedT);
31|      samples.push({ rtt, offset: serverAt + rtt / 2 - receiveTime });
32|      while (samples.length > history) samples.shift();
33|    },
34|    /** Best offset estimate, or null before the first pong. */
35|    offset() {
36|      let best = null;
37|      for (const s of samples) if (!best || s.rtt < best.rtt) best = s;
38|      return best ? best.offset : null;
39|    },
40|    /** True once at least one pong has been measured. */
41|    synced() { return samples.length > 0; },
42|    /** Convert a local time to the master clock. Returns null while unsynced. */
43|    serverNow(localNow) {
44|      const offset = this.offset();
45|      return offset === null ? null : localNow + offset;
46|    },
47|  };
48|}", "total_lines": 48, "file_size": 2272, "truncated": false, "is_binary": false, "is_image": false, "not_found": false}

{"content": "1|/**
2| * Arcade car physics using a kinematic bicycle model.
3| * PURE: no DOM, no WebGL — runs in Node for tests.
4| *
5| * Car state: position (x, z), heading (rad, 0 = facing +Z / south), speed (m/s,
6| * negative when reversing), steer (front wheel angle in rad, + = left).
7| */
8|import { approach } from '../core/math.js';
9|
10|/** Tuning for a typical German taxi (mid-size saloon). */
11|export const TAXI = {
12|  wheelBase: 2.9, // m between axles
13|  trackWidth: 1.64, // m between left and right wheels
14|  wheelRadius: 0.34,
15|  maxSteer: 0.6, // rad at standstill
16|  steerRate: 2.5, // rad/s the steering wheel can turn
17|  maxLateralAccel: 14, // m/s² — arcade grip (a real saloon manages ~9)
18|  engineAccel: 6.5, // m/s² at standstill, fades out towards maxSpeed
19|  brakeDecel: 14,
20|  reverseAccel: 4,
21|  maxSpeed: 36, // m/s ≈ 130 km/h
22|  maxReverse: 8,
23|  rollingResistance: 0.4, // m/s²
24|  airDrag: 0.0022, // m/s² per (m/s)²
25|  handbrakeDecel: 9,
26|  collisionRadius: 0.95, // the body is approximated by two circles
27|  collisionOffset: 1.45, // their distance from the centre along the car axis
28|  restitution: 0.25, // bounce on impact
29|};
30|
31|export function createCar({ x, z, heading }) {
32|  return { x, z, heading, speed: 0, steer: 0, wheelSpin: 0 };
33|}
34|
35|/**
36| * Advances the car by dt seconds.
37| * input = { throttle: 0..1, brake: 0..1, steer: -1..1 (+ = left), handbrake: bool }
38| */
39|export function stepCar(car, input, spec, dt) {
40|  // Grip-limited steering: never ask the tyres for more than maxLateralAccel (v²/L·tan δ ≤ a).
41|  const steerLimit = Math.min(spec.maxSteer, Math.atan((spec.maxLateralAccel * spec.wheelBase) / (car.speed * car.speed + 1e-6)));
42|  car.steer = approach(car.steer, input.steer * steerLimit, spec.steerRate * dt);
43|
44|  // Throttle accelerates forward (or brakes while rolling backwards), brake does the opposite.
45|  const v = car.speed;
46|  let accel = 0;
47|  if (input.throttle) accel += v < -0.5 ? spec.brakeDecel : input.throttle * spec.engineAccel * (1 - Math.max(v, 0) / spec.maxSpeed);
48|  if (input.brake) accel -= v > 0.5 ? spec.brakeDecel : input.brake * spec.reverseAccel * (1 + Math.min(v, 0) / spec.maxReverse);
49|  car.speed += accel * dt;
50|
51|  // Resistances oppose motion but never reverse it on their own.
52|  let drag = spec.rollingResistance + spec.airDrag * car.speed * car.speed;
53|  if (input.handbrake) drag += spec.handbrakeDecel;
54|  car.speed -= Math.sign(car.speed) * Math.min(Math.abs(car.speed), drag * dt);
55|
56|  // Bicycle model: yaw rate follows from speed, wheel base and steering angle.
57|  const yawRate = (car.speed / spec.wheelBase) * Math.tan(car.steer) * (input.handbrake ? 1.4 : 1);
58|  car.heading += yawRate * dt;
59|  car.x += Math.sin(car.heading) * car.speed * dt;
60|  car.z += Math.cos(car.heading) * car.speed * dt;
61|  car.wheelSpin = (car.wheelSpin + (car.speed / spec.wheelRadius) * dt) % (Math.PI * 2);
62|  return car;
63|}", "total_lines": 63, "file_size": 2853, "truncated": false, "is_binary": false, "is_image": false, "not_found": false}

{"content": "1|/**
2| * Pure track layout for the multiplayer race: a 200 m straight run eastwards
3| * along *Unter den Linden*, starting just past the Brandenburger-Tor-style
4| * gate (the solo mode's own spawn road). Derived ONLY from the shared city
5| * data, so every client computing it from the same seed gets the same track.
6| *
7| * Coordinates: the city generator's plane — north = −z, so east = +x and
8| * "facing east" = heading Math.PI / 2 (like cityGen's spawn).
9| *
10| * Pure data in, pure data out, runs in Node for the tests. Grid slots are
11| * validated "place-only" against the city colliders: every seat must clear
12| * buildings, medians, gate pillars and the world border before the race uses
13| * it. Counts toward the size budget — kept tight.
14| */
15|import { TAXI } from '../vehicle/carPhysics.js';
16|import { pushOut } from '../vehicle/collision.js';
17|
18|export const TRACK_LENGTH = 200;
19|const SLOT_GAP = 3.4; // grid spacing in the lane, north→south
20|const GRID_MARGIN = 1.5; // corridor clear of the colliders on both sides
21|
22|/**
23| * buildTrack(city, playerCount) →
24| *   { street, start, grid, finish, ampel, corridor, laneZ }
25| *
26| * - start   {x, z, heading}: the line the grid stands on
27| * - grid    [{x, z, heading}]: exactly playerCount seats, pole position first
28| * - finish  {x, z0, z1}: the chequered line segment across the racing lane
29| * - ampel   {x, z, heading}: the start light pole, on the central line ahead
30| * - corridor {x0, z0, x1, z1}: rect that must stay free of colliders, used
31| *   by the invariant tests ("track is fully on road, nothing in the way")
32| */
33|export function buildTrack(city, playerCount) {
34|  if (!Number.isInteger(playerCount) || playerCount < 2 || playerCount > 4)
35|    throw new RangeError('track: needs 2–4 players');
36|  const gate = city.landmarks.find((l) => l.kind === 'gate');
37|  const boulevard = city.streetsEW.find((s) => s.kind === 'boulevard');
38|  if (!gate || !boulevard) throw new RangeError('track: city has no boulevard or gate');
39|  const cfg = city.config;
40|
41|  // Start past the first north-south crossing east of the gate, so the grid
42|  // stands on an ordinary stretch of the boulevard, not across a junction.
43|  // (The solo mode's spawn is gate.x + 30 — at least that far east.)
44|  const crossing = city.streetsNS.find((s) => s.center + s.width / 2 > gate.x + 10);
45|  const start = {
46|    x: Math.max(gate.x + 30, (crossing ? crossing.center + crossing.width / 2 : gate.x) + 8),
47|    z: boulevard.center + cfg.medianWidth / 2 + 3.5,
48|    heading: Math.PI / 2,
49|  };
50|  const finish = {
51|    x: start.x + TRACK_LENGTH,
52|    z0: boulevard.center + cfg.medianWidth / 2 + GRID_MARGIN,
53|    z1: boulevard.center + cfg.boulevardWidth / 2 - GRID_MARGIN,
54|  };
55|  if (finish.x + GRID_MARGIN > city.bounds.x1 - 10)
56|    throw new RangeError('track: 200 m do not fit east of the gate');
57|
58|  // Seats side by side across the racing lane, starting just inside the clear band.
59|  const grid = Array.from({ length: playerCount }, (_, i) => ({
60|    x: start.x,
61|    z: start.z - 1.5 + i * SLOT_GAP,
62|    heading: Math.PI / 2,
63|  }));
64|  for (const slot of grid) {
65|    for (const off of [TAXI.collisionOffset, -TAXI.collisionOffset]) {
66|      if (pushOut(slot.x + off, slot.z, TAXI.collisionRadius, city.colliders))
67|        throw new RangeError('track: grid slot collides with the city');
68|    }
69|  }
70|  for (let a = 0; a < grid.length; a++)
71|    for (let b = a + 1; b < grid.length; b++)
72|      if (Math.hypot(grid[a].x - grid[b].x, grid[a].z - grid[b].z) < SLOT_GAP - 0.2)
73|        throw new RangeError('track: grid slots overlap');
74|
75|  const corridor = {
76|    x0: start.x - GRID_MARGIN * 1.5,
77|    z0: boulevard.center + cfg.medianWidth / 2 + 0.5,
78|    x1: finish.x + GRID_MARGIN,
79|    z1: boulevard.center + cfg.boulevardWidth / 2 - 0.5,
80|  };
81|  for (const c of city.colliders) {
82|    if (c.type === 'box') {
83|      if (c.x0 < corridor.x1 && c.x1 > corridor.x0 && c.z0 < corridor.z1 && c.z1 > corridor.z0)
84|        throw new RangeError('track: something box-shaped is standing in the corridor');
85|    } else if (Math.max(corridor.x0 - c.x, c.x - corridor.x1, 0) ** 2 + Math.max(corridor.z0 - c.z, c.z - corridor.z1, 0) ** 2 < c.r * c.r)
86|      throw new RangeError('track: something round is standing in the corridor');
87|  }
88|
89|  return {
90|    street: 'Unter den Linden',
91|    start,
92|    grid,
93|    finish,
94|    ampel: { x: start.x + 12, z: boulevard.center, heading: -Math.PI / 2 },
95|    corridor,
96|    laneZ: start.z,
97|  };
98|}", "total_lines": 98, "file_size": 4415, "truncated": false, "is_binary": false, "is_image": false, "not_found": false}

{"content": "1|/**
2| * Procedural Berlin-style city generator.
3| *
4| * PURE DATA: no DOM, no WebGL. Takes a seed, returns a plain object that the
5| * mesh builder turns into geometry and the physics uses for collisions.
6| * Runs in Node too, which is how the tests exercise it.
7| *
8| * Layout (top view, north = -Z):
9| *
10| *   |  park  | altbau | altbau | ...   <- block rows separated by streets
11| *   ===[gate]==== Unter den Linden ===   <- boulevard with a linden-tree median
12| *   |  park  | altbau | plaza(TV tower)
13| *   ~~~~~~~~~~~~~~ Spree ~~~~~~~~~~~~~~   <- river row, crossed by bridges
14| *   | altbau | platte | altbau | ...
15| */
16|import { Rng } from '../core/rng.js';
17|
18|export const DEFAULT_CITY = {
19|  seed: 1989,
20|  blocksX: 8, // block columns (west -> east)
21|  blocksZ: 7, // block rows (north -> south), one of them becomes the river
22|  blockMin: 70, // block edge length range in metres
23|  blockMax: 105,
24|  streetWidth: 14,
25|  boulevardWidth: 36,
26|  medianWidth: 8,
27|  riverWidth: 46,
28|  sidewalk: 4,
29|  curbHeight: 0.15,
30|};
31|
32|const NAMES_NS = ['Friedrichstraße', 'Schönhauser Allee', 'Kastanienallee', 'Rosenthaler Straße', 'Chausseestraße', 'Brunnenstraße', 'Wilhelmstraße', 'Mehringdamm', 'Kottbusser Damm', 'Prenzlauer Allee', 'Greifswalder Straße', 'Warschauer Straße'];
33|const NAMES_EW = ['Torstraße', 'Invalidenstraße', 'Oranienstraße', 'Kantstraße', 'Bernauer Straße', 'Skalitzer Straße', 'Gneisenaustraße', 'Danziger Straße', 'Leipziger Straße', 'Kochstraße', 'Wiener Straße', 'Pappelallee'];
34|const NAMES_UFER = ['Reichpietschufer', 'Schiffbauerdamm', 'Märkisches Ufer', 'Fraenkelufer', 'Paul-Lincke-Ufer', 'Maybachufer'];
35|
36|/** Colors are stored as 0xRRGGBB so the data stays renderer-agnostic. */
37|const PALETTE = {
38|  altbau: [0xe8dcc0, 0xd9b77e, 0xd99a82, 0xc9b79c, 0xbdbdb5, 0xe5d38f, 0xa9b8a6, 0x9fb0bf, 0xedebe4, 0xa65e46],
39|  roof: [0x8a4b3a, 0x55575c, 0x7c8085, 0x6b3f33],
40|  platte: [0xc8c4b8, 0xb5b9b5, 0xd2c7a8, 0xbfae95],
41|};
42|
43|export function generateCity(options = {}) {
44|  const cfg = { ...DEFAULT_CITY, ...options };
45|  if (cfg.blocksX < 4 || cfg.blocksZ < 5) throw new RangeError('City needs at least 4x5 blocks.');
46|  const root = new Rng(cfg.seed);
47|  const layoutRng = root.fork('layout');
48|  const nameRng = root.fork('names');
49|  const treeRng = root.fork('trees');
50|
51|  // 1. Pick the special rows: the river replaces one block row, the boulevard is one E-W street.
52|  const riverRow = layoutRng.int(Math.ceil(cfg.blocksZ / 2), cfg.blocksZ - 2);
53|  const boulevard = layoutRng.int(2, riverRow - 1);
54|
55|  // 2. Lay out streets and blocks along both axes.
56|  const blockSize = () => layoutRng.range(cfg.blockMin, cfg.blockMax);
57|  const xs = layoutAxis(cfg.blocksX, blockSize, () => cfg.streetWidth);
58|  const zs = layoutAxis(
59|    cfg.blocksZ,
60|    (r) => (r === riverRow ? cfg.riverWidth : blockSize()),
